<?php
require_once __DIR__.'/../includes/auth.php';require_login();$sid=filter_input(INPUT_GET,'subject_id',FILTER_VALIDATE_INT);$grade=(int)user()['grade_id'];$gradeNumber=user_grade_number();$medium=(string)user()['medium'];$uid=(int)user()['id'];
$subject=$sid?query_one("SELECT s.* FROM subjects s WHERE s.id=? AND s.grade_id=? AND s.status='active' AND EXISTS(SELECT 1 FROM lessons l WHERE l.subject_id=s.id AND l.content_source='textbook' AND l.status='active' AND (l.medium='All' OR l.medium=?))",'iis',[$sid,$grade,$medium]):null;if(!$subject){flash('error','No verified textbook lessons are available for this subject and medium.');redirect('student/subjects.php');}
$s=db()->prepare("SELECT l.id,l.display_order,l.title_en,l.title_si,l.title_ta,l.short_description_en,l.short_description_si,l.short_description_ta,u.unit_number,lp.opened_at,lp.completed_at,(SELECT q.id FROM quizzes q WHERE q.lesson_id=l.id AND q.status='active' LIMIT 1) quiz_id FROM lessons l JOIN units u ON u.id=l.unit_id LEFT JOIN lesson_progress lp ON lp.lesson_id=l.id AND lp.user_id=? WHERE l.subject_id=? AND l.grade_id=? AND l.content_source='textbook' AND l.status='active' AND (l.medium='All' OR l.medium=?) ORDER BY l.display_order,u.unit_number");$s->bind_param('iiis',$uid,$sid,$grade,$medium);$s->execute();$res=$s->get_result();$pageTitle=locale_value($subject,'name');include __DIR__.'/../includes/header.php';?>
<style>.lesson-row{display:grid;grid-template-columns:54px 1fr auto;gap:15px;align-items:center;text-decoration:none;color:inherit}.lesson-number{display:grid;place-items:center;width:52px;height:52px;border-radius:17px;background:#efedff;color:var(--violet);font-size:1.2rem;font-weight:900}.lesson-row h2{margin:0 0 5px}.lesson-row p{margin:0}.lesson-state{text-align:right}@media(max-width:600px){.lesson-row{grid-template-columns:48px 1fr}.lesson-state{grid-column:2;text-align:left}}</style>
<p><a href="subjects.php">← <?=tr('subjects')?></a></p><section class="card"><span class="badge"><?=e($subject['icon'])?> Grade <?=$gradeNumber?> textbook</span><h1><?=e(locale_value($subject,'name'))?></h1><p class="muted">Select a lesson for short notes, examples, a summary, AI tutoring and its quiz.</p></section>
<?php while($r=$res->fetch_assoc()):?><a class="card lesson-row" href="lesson.php?id=<?=intval($r['id'])?>"><span class="lesson-number"><?=intval($r['display_order'])?></span><span><h2><?=e(locale_value($r,'title'))?></h2><p class="muted"><?=e(locale_value($r,'short_description'))?></p></span><span class="lesson-state"><?php if($r['completed_at']):?><span class="badge">✓ Completed</span><?php elseif($r['opened_at']):?><span class="badge">Continue</span><?php else:?><span class="badge">Start</span><?php endif;?><small style="display:block;margin-top:7px"><?=$r['quiz_id']?'5-question quiz':'Notes'?></small></span></a><?php endwhile;?>
<?php include __DIR__.'/../includes/footer.php';
